(5864793, 853229, 111808, '<td valign="top">There is something elegantly profound in this simple photograph. Survival Counts.</td>', 'There is something elegantly profound in this simple photograph. Survival Counts.', '2010-02-12 15:22:10.000000', NULL, 1),
