INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5866618, 853197, 96881, '<td valign="top">"Raindrops keep falling on my head.......but that doesn''t mean my eyes will still be turning red"<br/> <br/>Abstract, which is what I think this challenge did need.  Sorry about the song, but that is what jumped straight into my head.......Love the composition, the black band and the two areas of colour work so well......this composition works brilliantly.............not voting cause I am in the challenge, but you have one of the better images for the Challenge description</td>', '"Raindrops keep falling on my head.......but that doesn''t mean my eyes will still be turning red" Abstract, which is what I think this challenge did need.  Sorry about the song, but that is what jumped straight into my head.......Love the composition, the black band and the two areas of colour work so well......this composition works brilliantly.............not voting cause I am in the challenge, but you have one of the better images for the Challenge description', '2010-02-14 14:11:42.000000', NULL, 1),
